import React, { useState } from "react";
import axios from "axios";

const Form = () => {
const [inputValue, setInputValue] = useState("");
const [responseMessage, setResponseMessage] = useState("");

const handleChange = (event) => {
setInputValue(event.target.value);
};

const handleSubmit = async (event) => {
event.preventDefault();
try {
const response = await axios.post("http://127.0.0.1:5000/api/post-data", {
name: inputValue,
});
setResponseMessage(response.data.received.name);
setInputValue("");
} catch (error) {
console.error("Error sending data:", error);
}
};

return (
<div style={{ textAlign: "center", marginTop: "50px" }}>
<h2>React Form to Send Data to Flask</h2>
<form onSubmit={handleSubmit}>
<input
type="text"
value={inputValue}
onChange={handleChange}
placeholder="Enter something..."
required
style={{ padding: "8px", marginRight: "10px" }}
/>
<button type="submit" style={{ padding: "8px 15px" }}>Submit</button>
</form>
{responseMessage && <p>Response: {responseMessage}</p>}
</div>
);
};

export default Form;
